using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> typeInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {typeInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), typeInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): check without throwing ---
// With the default resolver, Person resolves fine:
if (options.TryGetTypeInfo<Person>(out var personInfo))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded: {personInfo!.Type.Name}");
}

// Use a custom resolver that only knows about Person — Stream will NOT resolve:
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
        .WithAddedModifier(ti =>
        {
            // Allow only Person
            if (ti.Type != typeof(Person))
                ti.Properties.Clear(); // still "resolves" technically
        })
};

// Build a resolver that truly returns null for unknown types:
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new PersonOnlyResolver())
};

if (restrictedOptions.TryGetTypeInfo<Person>(out var found))
{
    Console.WriteLine($"TryGetTypeInfo<Person> on restricted resolver: found ({found!.Type.Name})");
}

if (!restrictedOptions.TryGetTypeInfo<Stream>(out var notFound))
{
    Console.WriteLine($"TryGetTypeInfo<Stream> on restricted resolver: not found (returned {notFound})");
}

Console.WriteLine("Done.");

// --- Supporting types ---
public record Person(string Name, int Age);

/// A resolver that only provides metadata for Person.
sealed class PersonOnlyResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);
        return null; // unknown type → TryGetTypeInfo returns false
    }
}

